@Composable
private fun DetectionContextBanner(
    latestDetection: DetectionHistoryEntity?,
    hasCustomSelected: Boolean,
    onResetReference: () -> Unit,
    onOpenScan: () -> Unit
) {
    Card(
        modifier = Modifier
            .fillMaxWidth()
            .padding(horizontal = 16.dp, vertical = 8.dp),
        shape = RoundedCornerShape(12.dp),
        colors = CardDefaults.cardColors(containerColor = Color.White),
        border = BorderStroke(1.dp, ChatBorderHairline)
    ) {
        if (latestDetection != null) {
            val confidenceStr = String.format(Locale.US, "%.1f%%", latestDetection.confidence * 100f)
            val (urgLabel, urgBg, urgFg) = when (latestDetection.urgensi.uppercase()) {
                "EDUKASI_MANDIRI" -> Triple("Edukasi Mandiri", GreenSoft, GreenSuccess)
                "KONTROL_RUTIN" -> Triple("Kontrol Rutin", AmberSoft, AmberText)
                "SEGERA_KE_DOKTER" -> Triple("Segera ke Dokter", RedSoft, RedError)
                else -> Triple(latestDetection.urgensi, SurfaceBlue, ChatTextPrimary)
            }
            Column(modifier = Modifier.padding(12.dp)) {
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Column(modifier = Modifier.weight(1f)) {
                        Text(
                            text = if (hasCustomSelected) "Referensi Scan Dipilih" else "Referensi Scan Mulut Aktif",
                            color = ChatPrimaryBlue,
                            fontSize = 11.sp,
                            fontWeight = FontWeight.SemiBold
                        )
                        Text(
                            text = "${latestDetection.kelas.replace("_", " ")} ($confidenceStr)",
                            color = ChatTextPrimary,
                            fontSize = 15.sp,
                            fontWeight = FontWeight.SemiBold
                        )
                    }
                    Box(
                        modifier = Modifier
                            .background(urgBg, RoundedCornerShape(8.dp))
                            .padding(horizontal = 8.dp, vertical = 4.dp)
                    ) {
                        Text(text = urgLabel, color = urgFg, fontSize = 11.sp, fontWeight = FontWeight.SemiBold)
                    }
                }
                if (latestDetection.catatanKeluhan.isNotBlank()) {
                    Spacer(modifier = Modifier.height(6.dp))
                    Text(
                        text = "Keluhan: ${latestDetection.catatanKeluhan}",
                        color = ChatTextMuted,
                        fontSize = 12.sp
                    )
                }
                if (hasCustomSelected) {
                    Spacer(modifier = Modifier.height(4.dp))
                    TextButton(
                        onClick = onResetReference,
                        contentPadding = PaddingValues(0.dp)
                    ) {
                        Text(
                            text = "Gunakan hasil scan terbaru",
                            color = ChatPrimaryBlue,
                            fontSize = 12.sp,
                            fontWeight = FontWeight.Medium
                        )
                    }
                }
            }
        } else {
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(12.dp),
                verticalAlignment = Alignment.CenterVertically
            ) {
                Icon(
                    imageVector = Icons.Filled.MedicalServices,
                    contentDescription = null,
                    tint = ChatPrimaryBlue,
                    modifier = Modifier.size(20.dp)
                )
                Spacer(modifier = Modifier.width(10.dp))
                Column(modifier = Modifier.weight(1f)) {
                    Text(
                        text = "Mode Konsultasi Umum",
                        color = ChatTextPrimary,
                        fontSize = 14.sp,
                        fontWeight = FontWeight.SemiBold
                    )
                    Text(
                        text = "Lakukan scan mulut agar AI memahami kondisi gigi Anda.",
                        color = ChatTextMuted,
                        fontSize = 12.sp
                    )
                }
                Spacer(modifier = Modifier.width(8.dp))
                OutlinedButton(
                    onClick = onOpenScan,
                    border = BorderStroke(1.dp, ChatPrimaryBlue),
                    shape = RoundedCornerShape(8.dp),
                    contentPadding = PaddingValues(horizontal = 10.dp, vertical = 6.dp)
                ) {
                    Icon(
                        imageVector = Icons.Filled.CameraAlt,
                        contentDescription = null,
                        tint = ChatPrimaryBlue,
                        modifier = Modifier.size(14.dp)
                    )
                    Spacer(modifier = Modifier.width(4.dp))
                    Text("Scan", color = ChatPrimaryBlue, fontSize = 12.sp, fontWeight = FontWeight.Medium)
                }
            }
        }
    }
}

